         for (int i = 0; i < 1000; ++i) {
          pt = ro + rd * t;
          d = map (pt);
          if (d < 0.001 || t + d >= 1000.0) {
           break;
          }
          t += d;
         }
         return d <= 0.001 ? t : 1000.0;
